<template>
  <Layout>
    <template #topbar-title><div class="top-title"><span>ACCOUNTING</span><strong>Tally Integration Center</strong></div></template>
    <div class="tally-page">
      <header class="hero"><div><span class="eyebrow">SAFE IMPORT WORKSPACE</span><h1>Connect Tally to {{ company.name }}</h1><p>Pair a local or hosted Windows connector, review what was found, then approve only verified mappings.</p></div><button class="primary" @click="showConnect = true">Connect Tally</button></header>
      <div class="notice"><strong>BillIQ keeps Tally read-only.</strong> Data is staged and analyzed before posting. Local TallyPrime and hosted Windows/RDP Tally are supported through the connector. No provider-specific cloud API is enabled unless BillIQ supplies and verifies one.</div>
      <section class="cards"><article><small>Connections</small><strong>{{ overview.counts.connections }}</strong></article><article><small>Needs mapping</small><strong>{{ overview.counts.unmatched }}</strong></article><article><small>Awaiting review</small><strong>{{ overview.counts.pending_approval }}</strong></article><article><small>Last sync</small><strong>{{ overview.latest_batch ? overview.latest_batch.status : 'Not started' }}</strong></article></section>
      <section class="grid">
        <article class="panel"><div class="panel-heading"><div><span class="eyebrow">STEP 1</span><h2>Connections</h2></div><button class="secondary" @click="showConnect = true">Add connection</button></div><div v-if="!overview.connections.length" class="empty">No connector is paired yet.</div><div v-for="connection in overview.connections" :key="connection.id" class="connection"><div><strong>{{ connection.name }}</strong><span>{{ connection.location === 'local' ? 'Local Windows connector' : 'Hosted Windows / RDP connector' }}</span><small>{{ connection.company_name || 'Company not selected' }} · {{ connection.status }}</small></div><div class="actions"><button class="secondary" :disabled="!connection.endpoint_url" :title="connection.endpoint_url ? 'Test configured endpoint' : 'Run the connector test on the Windows Tally host'" @click="test(connection)">Test endpoint</button><button class="secondary" @click="pair(connection)">Pair</button></div></div><p class="helper">For local or hosted Windows Tally, connectivity to Tally is tested by the launcher on the Tally host. The BillIQ button tests only a configured HTTPS endpoint.</p></article>
        <article class="panel"><div class="panel-heading"><div><span class="eyebrow">STEP 2</span><h2>Setup checklist</h2></div></div><ol class="steps"><li :class="{done: overview.connections.length}"><b>Choose location</b><span>Local TallyPrime or hosted cloud setup.</span></li><li :class="{done: connected}"><b>Pair connector</b><span>Use the one-time code; never expose port 9000 publicly.</span></li><li :class="{done: overview.latest_batch}"><b>Fetch and analyze</b><span>Masters, vouchers and inventory are staged for review.</span></li><li><b>Review mappings</b><span>Resolve high-risk or duplicate records before approval.</span></li></ol></article>
      </section>
      <section class="panel"><div class="panel-heading"><div><span class="eyebrow">STEP 3</span><h2>Sync history</h2></div></div><div v-if="!overview.batches.length" class="empty">Your first sync will appear here.</div><div v-for="batch in overview.batches" :key="batch.id" class="batch"><div><strong>Batch #{{ batch.id }}</strong><span>{{ batch.mode }} · {{ batch.records_received }} records · {{ batch.status }}</span></div><div class="actions"><button class="secondary" @click="reviewBatch(batch)">Review records</button><button class="secondary" @click="reconcile(batch)">Reconcile</button><button v-if="batch.status === 'ready_for_review'" class="primary small" @click="approve(batch)">Approve review</button><button v-if="batch.status === 'approved'" class="primary small" @click="importBatch(batch)">Import approved</button></div></div></section>
      <section v-if="selectedBatch" class="panel"><div class="panel-heading"><div><span class="eyebrow">REVIEW</span><h2>Batch #{{ selectedBatch.batch.id }} records</h2></div><button class="secondary" @click="selectedBatch = null">Close</button></div><p class="helper">Unsupported, unmatched and conflicting records must be resolved before approval. Financial posting is not performed from this screen.</p><div class="review-table"><div v-for="record in selectedBatch.records" :key="record.id" class="review-row"><div><strong>{{ record.source_name || 'Unnamed source' }}</strong><span>{{ record.source_type }} · {{ record.source_key }}</span></div><b :class="record.status">{{ record.status }}</b><small v-if="record.import_error">{{ record.import_error }}</small><small v-else-if="record.validation_json?.normalization_error">{{ record.validation_json.normalization_error }}</small></div></div></section>
      <div v-if="message" class="toast">{{ message }}</div>
      <div v-if="showConnect" class="modal-backdrop" @click.self="showConnect = false"><form class="modal" @submit.prevent="connect"><h2>Connect Tally</h2><label>Name<input v-model="form.name" required /></label><label>Location<select v-model="form.location"><option value="local">Local TallyPrime</option><option value="cloud">Hosted Tally</option></select></label><label v-if="form.location === 'cloud'">Cloud type<select v-model="form.cloud_type"><option value="api" disabled>Provider HTTPS API (not available)</option><option value="hosted_windows">Hosted Windows / RDP connector</option></select></label><p v-if="form.location === 'cloud'" class="helper">Hosted Tally uses the connector on the Windows/RDP host. Provider API connections are not enabled until a provider adapter and credentials are verified.</p><label>Endpoint URL <small>Optional for a connector setup; never publish Tally XML to the internet.</small><input v-model="form.endpoint_url" placeholder="https://provider.example/api" /></label><div class="modal-actions"><button type="button" class="secondary" @click="showConnect = false">Cancel</button><button class="primary" :disabled="busy">Create pairing code</button></div><p v-if="pairingCode" class="pairing">Pairing code: <strong>{{ pairingCode }}</strong><br><small>Enter this in the connector within 15 minutes. Treat it like a secret.</small></p></form></div>
    </div>
  </Layout>
</template>

<script setup>
import { computed, reactive, ref } from 'vue';
import axios from 'axios';
import Layout from '../Layout.vue';

const props = defineProps({ company: Object, overview: Object });
const overview = reactive(props.overview || { connections: [], batches: [], counts: { connections: 0, unmatched: 0, pending_approval: 0 }, latest_batch: null });
const showConnect = ref(false); const busy = ref(false); const message = ref(''); const pairingCode = ref(''); const selectedBatch = ref(null);
const form = reactive({ name: 'TallyPrime', location: 'local', cloud_type: 'hosted_windows', provider: '', endpoint_url: '' });
const connected = computed(() => overview.connections.some((c) => c.status === 'connected'));
const notify = (text) => { message.value = text; setTimeout(() => { message.value = ''; }, 5000); };
const connect = async () => { busy.value = true; try { const { data } = await axios.post('/app/accounting/tally/connections', form); overview.connections.unshift(data.connection); pairingCode.value = data.pairing_code; overview.counts.connections++; notify('Connection created. Pair the connector with the displayed code.'); } catch (e) { notify(e.response?.data?.message || 'Connection could not be created.'); } finally { busy.value = false; } };
const pair = async (connection) => { const code = window.prompt('Enter the pairing code shown by the connector setup:'); if (!code) return; try { const { data } = await axios.post(`/app/accounting/tally/connections/${connection.id}/pair`, { pairing_code: code }); Object.assign(connection, data.connection); notify('Connector paired. You can now run the connector.'); } catch (e) { notify(e.response?.data?.message || 'Pairing failed.'); } };
const test = async (connection) => { try { const { data } = await axios.post(`/app/accounting/tally/connections/${connection.id}/test`); notify(data.message); } catch (e) { notify(e.response?.data?.message || 'Connection test failed.'); } };
const reviewBatch = async (batch) => { try { const { data } = await axios.get(`/app/accounting/tally/batches/${batch.id}`); selectedBatch.value = data; } catch (e) { notify(e.response?.data?.message || 'Batch review could not be loaded.'); } };
const approve = async (batch) => { try { const { data } = await axios.post(`/app/accounting/tally/batches/${batch.id}/approve`); Object.assign(batch, data.batch); notify(data.message); } catch (e) { notify(e.response?.data?.message || 'Approval is blocked until mappings are resolved.'); } };
const reconcile = async (batch) => { try { const { data } = await axios.post(`/app/accounting/tally/batches/${batch.id}/reconcile`); notify(`${data.items.length} reconciliation checks recorded.`); } catch (e) { notify('Reconciliation could not be calculated.'); } };
const importBatch = async (batch) => { if (!window.confirm('Post this approved batch through BillIQ accounting and inventory services?')) return; try { const { data } = await axios.post(`/app/accounting/tally/batches/${batch.id}/import`); Object.assign(batch, data.batch); notify(data.message); } catch (e) { notify(e.response?.data?.message || 'Import failed and was rolled back.'); } };
</script>

<style scoped>
.tally-page{display:grid;gap:16px;padding:4px 0 28px;color:#142139}.hero{display:flex;justify-content:space-between;gap:18px;align-items:end}.eyebrow{color:#2457d6;font-size:10px;font-weight:900;letter-spacing:1.2px}.hero h1{margin:5px 0;color:#142139;font-size:26px}.hero p{margin:0;color:#758197;font-size:13px}.notice{padding:12px 14px;background:#eef4ff;border:1px solid #c7d7fe;border-radius:8px;color:#24457e;font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.cards article,.panel{background:#fff;border:1px solid #dfe6ef;border-radius:9px;padding:16px}.cards small,.connection span,.connection small,.batch span,.steps span,.helper,.review-row span,.review-row small{display:block;color:#758197;font-size:12px}.cards strong{display:block;margin-top:5px;font-size:22px}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:16px}.panel-heading{display:flex;justify-content:space-between;align-items:start;gap:12px;margin-bottom:14px}.panel h2{margin:4px 0 0;font-size:18px}.connection,.batch{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #edf1f5;padding:13px 0}.connection:first-of-type,.batch:first-of-type{border-top:0}.connection strong,.batch strong{display:block;font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap}.primary,.secondary{border:1px solid #d8e0eb;border-radius:8px;min-height:38px;padding:8px 12px;font-weight:800;cursor:pointer}.primary{background:#2457d6;color:#fff;border-color:#2457d6}.secondary{background:#fff;color:#24457e}.primary:disabled,.secondary:disabled{cursor:not-allowed;opacity:.5}.small{min-height:32px;font-size:11px}.steps{display:grid;gap:17px;margin:0;padding-left:22px}.steps li::marker{color:#9aa8bc;font-weight:900}.steps li.done::marker{color:#1d9b63}.steps b{display:block;font-size:13px}.empty{padding:20px;text-align:center;color:#758197;border:1px dashed #ccd6e3;border-radius:8px}.toast{position:fixed;right:24px;bottom:24px;background:#142139;color:#fff;border-radius:8px;padding:12px 16px;font-size:12px;box-shadow:0 10px 30px #14213933}.review-table{border:1px solid #edf1f5;border-radius:8px}.review-row{display:grid;grid-template-columns:1fr auto;gap:4px 12px;padding:10px 12px;border-top:1px solid #edf1f5}.review-row:first-child{border-top:0}.review-row b{font-size:11px;text-transform:uppercase}.review-row b.imported,.review-row b.matched{color:#15803d}.review-row b.error,.review-row b.unmatched,.review-row b.conflict{color:#b91c1c}.modal-backdrop{position:fixed;inset:0;background:#14213966;display:grid;place-items:center;padding:20px;z-index:5}.modal{display:grid;gap:12px;width:min(500px,100%);background:#fff;border-radius:12px;padding:20px;box-shadow:0 15px 50px #14213944}.modal h2{margin:0}.modal label{display:grid;gap:5px;color:#69758a;font-size:11px;font-weight:800;text-transform:uppercase}.modal input,.modal select{min-height:40px;border:1px solid #d8e0eb;border-radius:8px;padding:8px;font-size:13px}.modal label small{font-weight:500;text-transform:none}.modal-actions{display:flex;justify-content:end;gap:8px}.pairing{padding:12px;background:#ecfdf3;border:1px solid #bbf7d0;border-radius:8px;color:#166534;text-align:center}.pairing strong{font-size:22px;letter-spacing:2px}@media(max-width:900px){.hero,.grid{grid-template-columns:1fr;display:grid}.cards{grid-template-columns:1fr 1fr}}@media(max-width:560px){.cards{grid-template-columns:1fr}.connection,.batch{align-items:start;flex-direction:column}}
</style>
